"""Component framework.

A `CarComponent` attaches to a `Connector` and produces a mesh (plus optional
sub-connectors of its own, so that e.g. a dashboard can offer gauge-cluster and
vent connectors to further components).

Type matching uses the connector class hierarchy: a component that `accepts`
`PolygonConnector` also accepts `RectangleConnector` and `CircleConnector`.

`MorphableComponent` is the target-based flavour and uses *exactly* the same
machinery as the body: a fixed-topology parametric generator, a set of
`ModifierSpec`s turned into differential targets, and a `fit()` step that maps
the connector's geometry (radius, width, height, meta hints) onto modifier
values in [-1, 1].

Local frame convention for all components: build in the connector's local
frame where +Z is the mount normal (things grow along +Z), +X the connector's
major direction, origin at the connector origin.  `build()` transforms the
result into world space.
"""
from __future__ import annotations

import dataclasses
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Sequence, Tuple, Type
import numpy as np

from ..geometry.mesh import Mesh, Material
from ..geometry.frame import Frame
from ..connectors import Connector, PointConnector, PolygonConnector, RectangleConnector, CircleConnector
from ..morph.morphable import MorphableMesh, DifferentialTargetBuilder, ModifierSpec
from ..morph.target import Target, Modifier


@dataclass
class Palette:
    """Colours shared across components (from the config)."""
    paint: str = "#8a1c1c"
    trim: str = "#141416"
    chrome: str = "#c9ccd1"
    glass: str = "#7fa3b8"
    interior: str = "#2a2724"
    interior_accent: str = "#6b5a48"
    seat: str = "#3a332d"
    rim: str = "#b8bcc2"
    light: str = "#e8ecef"
    taillight: str = "#b3121b"
    wood: str = "#5a3b22"
    carpet: str = "#1c1a18"
    extras: Dict[str, str] = field(default_factory=dict)

    def color(self, key: str) -> str:
        return self.extras.get(key, getattr(self, key, "#808080"))


@dataclass
class BuildContext:
    measurements: Dict[str, float]
    hints: Dict[str, Any]
    palette: Palette
    rng: np.random.Generator
    depth: int = 0

    def material(self, name: str, color=None, alpha=1.0, shininess=0.3, emissive=0.0, metallic=0.0) -> Material:
        c = self.palette.color(name) if color is None else color
        return Material(name, Material.parse_color(c), alpha, shininess, emissive, metallic)


@dataclass
class ComponentResult:
    mesh: Mesh
    connectors: List[Connector] = field(default_factory=list)
    info: Dict[str, Any] = field(default_factory=dict)


class CarComponent:
    """Base class: procedural component bound to a connector type."""

    name: str = "component"
    accepts: Tuple[Type[Connector], ...] = (Connector,)
    default_for: Tuple[str, ...] = ()       # connector tags this is the default for
    priority: int = 0                       # higher wins among defaults for the same tag
    options: Dict[str, Any] = {}            # documented defaults
    description: str = ""

    @classmethod
    def can_attach(cls, connector: Connector) -> bool:
        return isinstance(connector, cls.accepts)

    def resolve_options(self, options: Optional[dict]) -> dict:
        o = dict(self.options)
        o.update(options or {})
        return o

    def build(self, connector: Connector, options: Optional[dict], ctx: BuildContext) -> ComponentResult:
        if not self.can_attach(connector):
            raise TypeError(f"{self.name} accepts {[t.__name__ for t in self.accepts]}, got {type(connector).__name__} ({connector.name})")
        opts = self.resolve_options(options)
        result = self.build_local(connector, opts, ctx)
        result.mesh.apply_frame(connector.frame)
        result.mesh.name = f"{connector.name}:{self.name}"
        for c in result.connectors:
            c.frame = c.frame.transformed(connector.frame.matrix)
            if isinstance(c, PolygonConnector):
                c._points = connector.frame.to_world(c._points)
            c.owner = connector.name
            c.name = f"{connector.name}/{c.name}"
        return result

    # subclasses implement this in the connector's local frame
    def build_local(self, connector: Connector, opts: dict, ctx: BuildContext) -> ComponentResult:
        raise NotImplementedError

    @classmethod
    def describe(cls) -> dict:
        return {
            "name": cls.name,
            "accepts": [t.__name__ for t in cls.accepts],
            "default_for": list(cls.default_for),
            "options": dict(cls.options),
            "description": cls.description,
            "morphable": issubclass(cls, MorphableComponent),
        }


class MorphableComponent(CarComponent):
    """Target-based component (same logic as the body).

    Subclasses define:
      params_cls        dataclass of generator parameters (canonical values)
      modifier_specs    list[ModifierSpec] -> differential targets
      generate(params)  fixed-topology mesh in the local frame
      fit(connector, opts, ctx) -> {modifier: value in [-1,1]}
      sub_connectors(connector, opts, ctx, values) -> local-frame connectors
    Variant generators (e.g. bench vs bucket seat) can be exposed as *macro*
    targets by overriding `macros()`.
    """

    params_cls: Type = None  # type: ignore
    modifier_specs: List[ModifierSpec] = []
    _libraries: Dict[str, MorphableMesh] = {}

    def canonical(self):
        return self.params_cls()

    def macros(self) -> Dict[str, Any]:
        return {}

    def generate(self, params) -> Mesh:
        raise NotImplementedError

    def fit(self, connector: Connector, opts: dict, ctx: BuildContext) -> Dict[str, float]:
        return {}

    def sub_connectors(self, connector: Connector, opts: dict, ctx: BuildContext, values: Dict[str, float]) -> List[Connector]:
        return []

    def library(self) -> MorphableMesh:
        key = f"{type(self).__module__}.{type(self).__name__}"
        lib = MorphableComponent._libraries.get(key)
        if lib is None:
            builder = DifferentialTargetBuilder(self.generate, self.canonical(), name=self.name)
            lib = builder.build(self.modifier_specs, macros=self.macros(), macro_group="variant")
            MorphableComponent._libraries[key] = lib
        return lib

    @staticmethod
    def ratio_to_value(actual: float, canonical: float, delta_minus: float, delta_plus: float) -> float:
        """Map a desired physical value onto a bipolar slider value (clamped)."""
        d = actual - canonical
        if d >= 0:
            return float(np.clip(d / delta_plus, 0, 1)) if delta_plus else 0.0
        return float(np.clip(d / delta_minus, -1, 0)) if delta_minus else 0.0

    def spec(self, name: str) -> ModifierSpec:
        for s in self.modifier_specs:
            if (s.name or s.param) == name:
                return s
        raise KeyError(name)

    def value_for(self, name: str, actual: float) -> float:
        s = self.spec(name)
        canon = getattr(self.canonical(), s.param)
        return self.ratio_to_value(actual, canon, s.delta_minus, s.delta_plus)

    def materials(self, ctx: BuildContext, opts: dict) -> Dict[str, Material]:
        return {}

    def build_local(self, connector: Connector, opts: dict, ctx: BuildContext) -> ComponentResult:
        values = self.fit(connector, opts, ctx)
        lib = self.library()
        for k in list(values):
            if k not in lib.modifiers:
                raise KeyError(f"{self.name}: fit() produced unknown modifier {k!r}")
        mesh = lib.morph(values)
        mesh.materials.update(self.materials(ctx, opts))
        subs = self.sub_connectors(connector, opts, ctx, values)
        return ComponentResult(mesh, subs, {"modifier_values": values})


# ------------------------------------------------------------------- registry
REGISTRY: Dict[str, Type[CarComponent]] = {}


def register(cls: Type[CarComponent]) -> Type[CarComponent]:
    if not cls.name or cls.name in REGISTRY:
        raise ValueError(f"component name missing or duplicate: {cls.name!r}")
    REGISTRY[cls.name] = cls
    return cls


def get_component(name: str) -> CarComponent:
    if name not in REGISTRY:
        raise KeyError(f"unknown component {name!r}; available: {sorted(REGISTRY)}")
    return REGISTRY[name]()


def default_component_for(connector: Connector) -> Optional[str]:
    """Pick the default component for a connector by its tags (then by type)."""
    best: Tuple[int, str] | None = None
    for name, cls in REGISTRY.items():
        if not cls.can_attach(connector):
            continue
        for tag in cls.default_for:
            if tag in connector.tags or tag == connector.name:
                score = cls.priority * 10 + (5 if tag == connector.name else 0)
                if best is None or score > best[0]:
                    best = (score, name)
    return best[1] if best else None


def describe_all() -> List[dict]:
    return [cls.describe() for cls in REGISTRY.values()]

"""Polygon mesh container with materials, vertex groups and face zones.

Faces are stored as a list of index tuples (quads and triangles mixed) so that
the loft topology stays readable; `triangulated()` gives an (M,3) array for
rendering.  Vertex *groups* (named vertex index sets) are the MakeHuman analogue
of landmark/joint vertex groups: connectors are derived from them so that they
follow the mesh when targets are applied.  Face *zones* are named face index
sets used for materials and for apertures (windows, lights) that are removed
from the body and handed to components as polygon connectors.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple
import numpy as np


@dataclass
class Material:
    name: str
    color: Tuple[float, float, float] = (0.7, 0.7, 0.7)
    alpha: float = 1.0
    shininess: float = 0.3
    emissive: float = 0.0
    metallic: float = 0.0

    @staticmethod
    def parse_color(c) -> Tuple[float, float, float]:
        if isinstance(c, str):
            s = c.lstrip("#")
            if len(s) == 3:
                s = "".join(ch * 2 for ch in s)
            return tuple(int(s[i : i + 2], 16) / 255.0 for i in (0, 2, 4))  # type: ignore
        c = tuple(float(v) for v in c)
        if max(c) > 1.0:
            c = tuple(v / 255.0 for v in c)
        return c  # type: ignore

    def with_color(self, c, name: Optional[str] = None) -> "Material":
        m = Material(name or self.name, Material.parse_color(c), self.alpha, self.shininess, self.emissive, self.metallic)
        return m

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "color": [round(v, 4) for v in self.color],
            "alpha": self.alpha,
            "shininess": self.shininess,
            "emissive": self.emissive,
            "metallic": self.metallic,
        }


DEFAULT_MATERIAL = Material("default")


class Mesh:
    def __init__(
        self,
        vertices=None,
        faces: Optional[Sequence[Sequence[int]]] = None,
        face_materials: Optional[Sequence[str]] = None,
        materials: Optional[Dict[str, Material]] = None,
        name: str = "mesh",
    ):
        self.name = name
        self.vertices = np.zeros((0, 3)) if vertices is None else np.asarray(vertices, dtype=float).reshape(-1, 3)
        self.faces: List[Tuple[int, ...]] = [tuple(int(i) for i in f) for f in (faces or [])]
        if face_materials is None:
            face_materials = [DEFAULT_MATERIAL.name] * len(self.faces)
        self.face_materials: List[str] = list(face_materials)
        self.materials: Dict[str, Material] = dict(materials or {})
        if DEFAULT_MATERIAL.name not in self.materials and DEFAULT_MATERIAL.name in self.face_materials:
            self.materials[DEFAULT_MATERIAL.name] = DEFAULT_MATERIAL
        self.groups: Dict[str, np.ndarray] = {}
        self.zones: Dict[str, np.ndarray] = {}
        self.lines: List[np.ndarray] = []  # decorative polylines (seams etc.), world coords (K,3)
        self.line_names: List[str] = []
        self.meta: Dict[str, Any] = {}     # generator bookkeeping (copied, not exported)

    # ------------------------------------------------------------- basics
    @property
    def n_vertices(self) -> int:
        return len(self.vertices)

    @property
    def n_faces(self) -> int:
        return len(self.faces)

    def copy(self) -> "Mesh":
        m = Mesh(self.vertices.copy(), list(self.faces), list(self.face_materials), dict(self.materials), self.name)
        m.groups = {k: v.copy() for k, v in self.groups.items()}
        m.zones = {k: v.copy() for k, v in self.zones.items()}
        m.lines = [l.copy() for l in self.lines]
        m.line_names = list(self.line_names)
        m.meta = dict(self.meta)
        return m

    def bounds(self) -> Tuple[np.ndarray, np.ndarray]:
        if self.n_vertices == 0:
            return np.zeros(3), np.zeros(3)
        return self.vertices.min(axis=0), self.vertices.max(axis=0)

    def add_material(self, mat: Material) -> Material:
        self.materials[mat.name] = mat
        return mat

    def set_material(self, name: str, face_indices=None):
        if face_indices is None:
            self.face_materials = [name] * self.n_faces
        else:
            for i in np.asarray(face_indices).ravel():
                self.face_materials[int(i)] = name

    def add_group(self, name: str, indices: Iterable[int]):
        self.groups[name] = np.asarray(list(indices), dtype=int)

    def add_zone(self, name: str, face_indices: Iterable[int]):
        self.zones[name] = np.asarray(list(face_indices), dtype=int)

    def add_line(self, pts, name: str = "line"):
        self.lines.append(np.asarray(pts, dtype=float).reshape(-1, 3))
        self.line_names.append(name)

    # ---------------------------------------------------------- transforms
    def transform(self, m4: np.ndarray) -> "Mesh":
        r, t = m4[:3, :3], m4[:3, 3]
        self.vertices = self.vertices @ r.T + t
        self.lines = [l @ r.T + t for l in self.lines]
        if np.linalg.det(r) < 0:
            self.faces = [tuple(reversed(f)) for f in self.faces]
        return self

    def translate(self, d) -> "Mesh":
        d = np.asarray(d, dtype=float)
        self.vertices = self.vertices + d
        self.lines = [l + d for l in self.lines]
        return self

    def scale(self, s) -> "Mesh":
        s = np.asarray(s, dtype=float)
        self.vertices = self.vertices * s
        self.lines = [l * s for l in self.lines]
        if np.ndim(s) and np.prod(np.sign(s)) < 0:
            self.faces = [tuple(reversed(f)) for f in self.faces]
        return self

    def apply_frame(self, frame) -> "Mesh":
        """Interpret current coordinates as local to `frame` and map to world."""
        return self.transform(frame.matrix)

    def mirrored(self, axis: int = 1) -> "Mesh":
        s = np.ones(3)
        s[axis] = -1.0
        m = self.copy()
        m.scale(s)
        return m

    # ---------------------------------------------------------- topology
    def merge(self, other: "Mesh", group_prefix: Optional[str] = None) -> "Mesh":
        off = self.n_vertices
        foff = self.n_faces
        self.vertices = np.vstack([self.vertices, other.vertices]) if self.n_vertices else other.vertices.copy()
        self.faces.extend(tuple(i + off for i in f) for f in other.faces)
        self.face_materials.extend(other.face_materials)
        for k, v in other.materials.items():
            self.materials.setdefault(k, v)
        for k, v in other.groups.items():
            key = f"{group_prefix}/{k}" if group_prefix else k
            self.groups[key] = v + off
        for k, v in other.zones.items():
            key = f"{group_prefix}/{k}" if group_prefix else k
            self.zones[key] = v + foff
        self.lines.extend(l.copy() for l in other.lines)
        self.line_names.extend(other.line_names)
        return self

    def remove_faces(self, face_indices) -> "Mesh":
        drop = set(int(i) for i in np.asarray(face_indices).ravel())
        if not drop:
            return self
        keep = [i for i in range(self.n_faces) if i not in drop]
        remap = {old: new for new, old in enumerate(keep)}
        self.faces = [self.faces[i] for i in keep]
        self.face_materials = [self.face_materials[i] for i in keep]
        new_zones = {}
        for k, v in self.zones.items():
            nv = np.asarray([remap[i] for i in v if i in remap], dtype=int)
            if len(nv):
                new_zones[k] = nv
        self.zones = new_zones
        return self

    def prune_unused_vertices(self) -> "Mesh":
        used = np.zeros(self.n_vertices, dtype=bool)
        for f in self.faces:
            used[list(f)] = True
        if used.all():
            return self
        remap = -np.ones(self.n_vertices, dtype=int)
        remap[used] = np.arange(used.sum())
        self.vertices = self.vertices[used]
        self.faces = [tuple(int(remap[i]) for i in f) for f in self.faces]
        self.groups = {k: remap[v][remap[v] >= 0] for k, v in self.groups.items()}
        return self

    def triangulated(self) -> Tuple[np.ndarray, np.ndarray]:
        """Return (tris (M,3) int, tri_face_index (M,) int) using fan triangulation."""
        tris, owner = [], []
        for fi, f in enumerate(self.faces):
            for k in range(1, len(f) - 1):
                tris.append((f[0], f[k], f[k + 1]))
                owner.append(fi)
        if not tris:
            return np.zeros((0, 3), dtype=int), np.zeros(0, dtype=int)
        return np.asarray(tris, dtype=int), np.asarray(owner, dtype=int)

    def _faces_by_size(self):
        groups: Dict[int, List[int]] = {}
        for i, f in enumerate(self.faces):
            groups.setdefault(len(f), []).append(i)
        return groups

    def face_normals(self) -> np.ndarray:
        """Unit normals per face (Newell's method, vectorised per polygon size)."""
        n = np.zeros((self.n_faces, 3))
        v = self.vertices
        for size, idx in self._faces_by_size().items():
            idx = np.asarray(idx)
            F = np.asarray([self.faces[i] for i in idx], dtype=int)  # (m, size)
            P = v[F]                                                 # (m, size, 3)
            Q = np.roll(P, -1, axis=1)
            nx = np.sum((P[:, :, 1] - Q[:, :, 1]) * (P[:, :, 2] + Q[:, :, 2]), axis=1)
            ny = np.sum((P[:, :, 2] - Q[:, :, 2]) * (P[:, :, 0] + Q[:, :, 0]), axis=1)
            nz = np.sum((P[:, :, 0] - Q[:, :, 0]) * (P[:, :, 1] + Q[:, :, 1]), axis=1)
            nn = np.column_stack([nx, ny, nz])
            l = np.linalg.norm(nn, axis=1, keepdims=True)
            n[idx] = nn / np.maximum(l, 1e-12)
        return n

    def face_centroids(self) -> np.ndarray:
        c = np.zeros((self.n_faces, 3))
        v = self.vertices
        for size, idx in self._faces_by_size().items():
            idx = np.asarray(idx)
            F = np.asarray([self.faces[i] for i in idx], dtype=int)
            c[idx] = v[F].mean(axis=1)
        return c

    def vertex_normals(self) -> np.ndarray:
        fn = self.face_normals()
        vn = np.zeros_like(self.vertices)
        for f, n in zip(self.faces, fn):
            vn[list(f)] += n
        l = np.linalg.norm(vn, axis=1, keepdims=True)
        return vn / np.maximum(l, 1e-12)

    def flip_normals(self) -> "Mesh":
        self.faces = [tuple(reversed(f)) for f in self.faces]
        return self

    def boundary_loops(self, face_indices=None) -> List[List[int]]:
        """Ordered vertex loops bounding the given faces (default: whole mesh)."""
        faces = self.faces if face_indices is None else [self.faces[i] for i in np.asarray(face_indices).ravel()]
        edge_count: Dict[Tuple[int, int], int] = {}
        directed: Dict[Tuple[int, int], int] = {}
        for f in faces:
            for a, b in zip(f, f[1:] + f[:1]):
                key = (min(a, b), max(a, b))
                edge_count[key] = edge_count.get(key, 0) + 1
                directed[(a, b)] = directed.get((a, b), 0) + 1
        boundary = [(a, b) for (a, b) in directed if edge_count[(min(a, b), max(a, b))] == 1]
        nxt: Dict[int, List[int]] = {}
        for a, b in boundary:
            nxt.setdefault(a, []).append(b)
        loops = []
        used = set()
        for a, b in boundary:
            if (a, b) in used:
                continue
            loop = [a]
            cur, prev = b, a
            used.add((a, b))
            guard = 0
            while cur != a and guard < 100000:
                loop.append(cur)
                cands = [c for c in nxt.get(cur, []) if (cur, c) not in used]
                if not cands:
                    break
                c = cands[0]
                used.add((cur, c))
                prev, cur = cur, c
                guard += 1
            loops.append(loop)
        return loops

    def zone_faces(self, name: str) -> np.ndarray:
        return self.zones.get(name, np.zeros(0, dtype=int))

    def subset(self, face_indices) -> "Mesh":
        idx = np.asarray(face_indices, dtype=int).ravel()
        m = Mesh(self.vertices.copy(), [self.faces[i] for i in idx], [self.face_materials[i] for i in idx], dict(self.materials), self.name)
        m.prune_unused_vertices()
        return m

    def stats(self) -> dict:
        lo, hi = self.bounds()
        return {
            "vertices": int(self.n_vertices),
            "faces": int(self.n_faces),
            "bounds_min": [round(float(v), 4) for v in lo],
            "bounds_max": [round(float(v), 4) for v in hi],
            "materials": sorted(self.materials.keys()),
        }

    def __repr__(self) -> str:  # pragma: no cover
        return f"Mesh({self.name!r}, {self.n_vertices} verts, {self.n_faces} faces)"

